def test_tilize_codegen_routes_accepted_to_codegen(device, shape, kwargs, dtype, layout):
    x = _make_input(shape, dtype)
    xt = ttnn.from_torch(x, dtype=dtype, layout=layout, device=device)
    golden = ttnn.to_torch(ttnn.tilize(xt, **kwargs, implementation=_NATIVE))
    entries_before = device.num_program_cache_entries()
    out = ttnn.tilize(xt, **kwargs, implementation=_ROUTED)
    assert_equal(golden, ttnn.to_torch(out))
    # The golden warms only the native program, so a routed dispatch that lands on
    # codegen must compile it. An unchanged cache means `auto` fell back to native and
    # the port's wins are unreachable through the public entry point.
    msg = "auto fell back to native for an accepted case (program cache did not grow); expected the codegen path"
    assert device.num_program_cache_entries() > entries_before, msg


